package android.widget;public class LinearLayout extends android.view.ViewGroup {public LinearLayout(Object c){}public LinearLayout(){}public void addView(android.view.View v,LayoutParams p){v.setLayoutParams(p);addView(v);}public static class LayoutParams extends android.view.ViewGroup.LayoutParams {public float weight;public LayoutParams(int w,int h){super(w,h);}public LayoutParams(int w,int h,float n){super(w,h);weight=n;}}}
